"""API errors without internals (generated by Shikshya, P1b.6 R2). An error DRF does not handle is logged with its
traceback and the request id; the client gets a plain message and that id, never the exception text. Previews
(DEBUG=1 in the environment) keep the raw error, which the build's own checks read; the environment is read, not
settings.DEBUG, because the test runner turns settings.DEBUG off."""
import logging
import os

from rest_framework.response import Response
from rest_framework.views import exception_handler

from .middleware import REQUEST_ID

logger = logging.getLogger("api.errors")


def safe_exception_handler(exc, context):
    response = exception_handler(exc, context)
    if response is not None or os.getenv("DEBUG", "0") == "1":
        return response
    logger.exception("Unhandled error in %s", type(context.get("view")).__name__)
    return Response({"detail": "Something went wrong on our side.", "request_id": REQUEST_ID.get()}, status=500)
